function polishPlural(value: number, singular: string, plural: string, genitivePlural: string): string {
  const lastTwo = value % 100;
  const last = value % 10;
  if (value === 1) return singular;
  if (last >= 2 && last <= 4 && (lastTwo < 12 || lastTwo > 14)) return plural;
  return genitivePlural;
}

function polishGoalCount(value: number): string {
  const lastTwo = value % 100;
  const last = value % 10;
  if (value === 1) return "1 cel związany";
  if (last >= 2 && last <= 4 && (lastTwo < 12 || lastTwo > 14)) return `${value} cele związane`;
  return `${value} celów związanych`;
}

export function formatPolishLicenseContinue(planCount: number, seatCount: number): string {
  return `Kontynuuj: ${planCount} ${polishPlural(planCount, "plan licencyjny", "plany licencyjne", "planów licencyjnych")} (${seatCount} ${polishPlural(seatCount, "licencja", "licencje", "licencji")}) →`;
}

function polishLicenseMix(text: string): string {
  return text.split("; ").map((entry) => {
    const match = entry.match(/^(\d+) (Microsoft 365 .+?) licenses?$/);
    if (!match) return entry;
    const count = Number(match[1]);
    return `${match[1]} ${polishPlural(count, "licencja", "licencje", "licencji")} ${match[2]}`;
  }).join("; ");
}

function translateMixedPlanDetails(text: string): string {
  const matches = [...text.matchAll(/(\d+) (Microsoft 365 .+?) licenses?: /g)];
  if (matches.length === 0) return translatePolish(text);
  return matches.map((match, index) => {
    const noteStart = match.index! + match[0].length;
    const noteEnd = matches[index + 1]?.index ?? text.length;
    const count = Number(match[1]);
    const plan = match[2];
    return `${match[1]} ${polishPlural(count, "licencja", "licencje", "licencji")} ${plan}: ${translatePolish(text.slice(noteStart, noteEnd).trim())}`;
  }).join(" ");
}

