export function translatePolish(text: string): string {
  const trimmed = text.trim();
  if (trimmed !== text) {
    const start = text.indexOf(trimmed);
    return text.slice(0, start) + translatePolish(trimmed) +
      text.slice(start + trimmed.length);
  }
  const exact = translations[text];
  if (exact) return exact;

  const mixedPlanMessage = text.match(/^Selected plan mix: (.*?)\. (Coverage applies only to users assigned each matching plan; the counts do not indicate whether the same users hold multiple plans\.|Entitlements apply only to users assigned each matching plan; the counts do not indicate whether the same users hold multiple plans\.|Server requirements apply to users or devices covered by each matching plan\.) (.*)$/);
  if (mixedPlanMessage) {
    const intro = mixedPlanMessage[2].startsWith("Server requirements")
      ? "Wymagania dotyczące serwerów odnoszą się do użytkowników lub urządzeń objętych danym planem."
      : "Zakres uprawnień obejmuje wyłącznie użytkowników, którym przypisano odpowiedni plan; liczby nie wskazują, czy te same osoby korzystają z kilku planów.";
    return `Wybrane plany licencyjne: ${polishLicenseMix(mixedPlanMessage[1])}. ${intro} ${translateMixedPlanDetails(mixedPlanMessage[3])}`;
  }

  const selectedPlanMix = text.match(/^Selected plan mix: (.+)\.$/);
  if (selectedPlanMix) return `Wybrane plany licencyjne: ${polishLicenseMix(selectedPlanMix[1])}.`;

  const microsoftPlanNames = text.split(" and ");
  if (microsoftPlanNames.length > 1 && microsoftPlanNames.every(name => /^Microsoft 365 /.test(name))) {
    return microsoftPlanNames.join(" i ");
  }

  for (const [pattern, format] of templates) {
    const match = text.match(pattern);
    if (match) return format(...match.slice(1));
  }

  const phrases = text.split(/(?<=[.!?])\s+(?=[A-Z0-9])/);
  if (phrases.length > 1) {
    const translated = phrases.map(translatePolish);
    if (translated.some((phrase, index) => phrase !== phrases[index])) return translated.join(" ");
  }
  return text;
}
